-- ============================================================================
-- medic — PostgreSQL schema
-- Generated by reverse-engineering the queries in medic/Api/* and medic/Dash/*.
-- Run against your local Postgres:
--
--   createdb nithish
--   psql -d nithish -f medic/Db/schema.postgres.sql
--
-- Notes
--  * Column names preserve the MixedCase used in the Go queries. Postgres
--    folds unquoted identifiers to lowercase, so we quote them here and the
--    Go code will work without changes IF the queries also quote them.
--    (Your current queries do NOT quote them, so see the "CASE-INSENSITIVE
--    VIEW" section at the bottom for an escape hatch.)
--  * Helper calendar tables `monthwise` and `weekwise` are populated with
--    data because the dashboard queries LEFT JOIN against them.
-- ============================================================================

BEGIN;

-- ---------------------------------------------------------------------------
-- userdata
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS userdata (
    "User_Id"   SERIAL PRIMARY KEY,
    "User"      TEXT NOT NULL UNIQUE,
    "Password"  TEXT NOT NULL,
    "Role"      TEXT NOT NULL CHECK ("Role" IN ('admin','manager','biller'))
);

-- ---------------------------------------------------------------------------
-- loginhistory
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS loginhistory (
    "Log_Id"     SERIAL PRIMARY KEY,
    "User_Id"    INTEGER NOT NULL REFERENCES userdata("User_Id") ON DELETE CASCADE,
    "Login_Time" TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "Logout_Time" TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_loginhistory_user ON loginhistory("User_Id");
CREATE INDEX IF NOT EXISTS idx_loginhistory_login_time ON loginhistory("Login_Time");

-- ---------------------------------------------------------------------------
-- medicinemaster
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS medicinemaster (
    "Med_Id"        SERIAL PRIMARY KEY,
    "MedicineName"  TEXT NOT NULL,
    "Brand"         TEXT,
    "test"          TEXT
);
CREATE UNIQUE INDEX IF NOT EXISTS ux_medmas_name_brand
    ON medicinemaster("MedicineName", COALESCE("Brand",''));

-- ---------------------------------------------------------------------------
-- stock (current on-hand quantity + price per medicine)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS stock (
    "Stock_Id" SERIAL PRIMARY KEY,
    "Med_id"   INTEGER NOT NULL UNIQUE REFERENCES medicinemaster("Med_Id") ON DELETE RESTRICT,
    "Qty"      INTEGER NOT NULL DEFAULT 0,
    "Price"    NUMERIC(12,2) NOT NULL DEFAULT 0
);

-- ---------------------------------------------------------------------------
-- billmaster (one row per bill)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS billmaster (
    "Bill_No"  SERIAL PRIMARY KEY,
    "BillDate" DATE NOT NULL DEFAULT CURRENT_DATE,
    "User_Id"  INTEGER NOT NULL REFERENCES userdata("User_Id"),
    "BillAmt"  NUMERIC(12,2) NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS idx_billmaster_date ON billmaster("BillDate");
CREATE INDEX IF NOT EXISTS idx_billmaster_user ON billmaster("User_Id");

-- ---------------------------------------------------------------------------
-- billdetails (line items per bill)
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS billdetails (
    "BillDetail_Id" SERIAL PRIMARY KEY,
    "Bill_No"       INTEGER NOT NULL REFERENCES billmaster("Bill_No") ON DELETE CASCADE,
    "Med_Id"        INTEGER NOT NULL REFERENCES medicinemaster("Med_Id"),
    "Qty"           INTEGER NOT NULL,
    "Amt"           NUMERIC(12,2) NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_billdetails_bill ON billdetails("Bill_No");

-- ---------------------------------------------------------------------------
-- monthwise — 12 fixed rows used to LEFT JOIN so every month appears even
-- with zero sales. Matches Dash/MonthlySale.go.
-- ---------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS monthwise (
    mnth TEXT PRIMARY KEY
);
INSERT INTO monthwise(mnth) VALUES
    ('January'),('February'),('March'),('April'),('May'),('June'),
    ('July'),('August'),('September'),('October'),('November'),('December')
ON CONFLICT DO NOTHING;

-- ---------------------------------------------------------------------------
-- weekwise — last N dates used by Dash/DailySales.go and Dash/Billerdash.go.
-- Populated as a view so it's always current (no cron needed).
-- ---------------------------------------------------------------------------
DROP TABLE IF EXISTS weekwise;
CREATE OR REPLACE VIEW weekwise AS
SELECT (CURRENT_DATE - (n || ' day')::interval)::date AS date_wise
FROM generate_series(0, 6) AS n;

COMMIT;

-- ============================================================================
-- STORED FUNCTIONS
-- The Go code calls MySQL functions via `select fn(?,?,...)`. Postgres
-- equivalents need to be authored — the signatures below match the call sites.
-- Fill in the bodies to match your MySQL implementations.
-- ============================================================================

-- log_entry(user_id) — inserts a loginhistory row and returns its id.
-- Called from Login.go / Logout.go.
CREATE OR REPLACE FUNCTION log_entry(p_user_id INTEGER)
RETURNS INTEGER AS $$
DECLARE v_id INTEGER;
BEGIN
    INSERT INTO loginhistory("User_Id") VALUES (p_user_id)
    RETURNING "Log_Id" INTO v_id;
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

-- add_user(username, password, role, ???) — signature from AddUser.go (4 args).
-- Adjust the 4th parameter to match what the Go call site passes.
CREATE OR REPLACE FUNCTION add_user(
    p_user TEXT,
    p_password TEXT,
    p_role TEXT,
    p_extra TEXT
) RETURNS INTEGER AS $$
DECLARE v_id INTEGER;
BEGIN
    INSERT INTO userdata("User","Password","Role")
    VALUES (p_user, p_password, p_role)
    RETURNING "User_Id" INTO v_id;
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

-- med_entry(name, brand, test) — 3 args from InsertMedMas.go
CREATE OR REPLACE FUNCTION med_entry(
    p_name TEXT,
    p_brand TEXT,
    p_test TEXT
) RETURNS INTEGER AS $$
DECLARE v_id INTEGER;
BEGIN
    INSERT INTO medicinemaster("MedicineName","Brand","test")
    VALUES (p_name, p_brand, p_test)
    RETURNING "Med_Id" INTO v_id;
    RETURN v_id;
END;
$$ LANGUAGE plpgsql;

-- stockEntry(med_id, qty, price, ???) — 4 args from StockUpdate.go.
-- Upsert pattern typical for a stock table.
CREATE OR REPLACE FUNCTION "stockEntry"(
    p_med_id INTEGER,
    p_qty INTEGER,
    p_price NUMERIC,
    p_extra TEXT
) RETURNS INTEGER AS $$
BEGIN
    INSERT INTO stock("Med_id","Qty","Price")
    VALUES (p_med_id, p_qty, p_price)
    ON CONFLICT ("Med_id") DO UPDATE
      SET "Qty"   = stock."Qty" + EXCLUDED."Qty",
          "Price" = EXCLUDED."Price";
    RETURN p_med_id;
END;
$$ LANGUAGE plpgsql;

-- billEntry(bill_no, med_id, qty, amt, user_id, bill_amt) — 6 args from BillEntry.go.
-- Adjust to match your Go call order if different.
CREATE OR REPLACE FUNCTION "billEntry"(
    p_bill_no INTEGER,
    p_med_id INTEGER,
    p_qty INTEGER,
    p_amt NUMERIC,
    p_user_id INTEGER,
    p_bill_amt NUMERIC
) RETURNS INTEGER AS $$
BEGIN
    -- Create/update the bill header.
    INSERT INTO billmaster("Bill_No","User_Id","BillAmt","BillDate")
    VALUES (p_bill_no, p_user_id, p_bill_amt, CURRENT_DATE)
    ON CONFLICT ("Bill_No") DO UPDATE
      SET "BillAmt" = EXCLUDED."BillAmt";

    -- Add line item.
    INSERT INTO billdetails("Bill_No","Med_Id","Qty","Amt")
    VALUES (p_bill_no, p_med_id, p_qty, p_amt);

    -- Decrement stock.
    UPDATE stock SET "Qty" = "Qty" - p_qty WHERE "Med_id" = p_med_id;

    RETURN p_bill_no;
END;
$$ LANGUAGE plpgsql;

